def solve(rows):
    groups = {}
    for row in rows:
        group, score, timestamp, name = row
        if group not in groups:
            groups[group] = []
        groups[group].append((score, timestamp, name))

    result = []
    for group in sorted(groups.keys()):
        group_data = groups[group]

        best_score = -1
        best_timestamp = float('inf')
        best_name = ''

        for score, timestamp, name in group_data:
            if score > best_score:
                best_score = score
                best_timestamp = timestamp
                best_name = name
            elif score == best_score:
                if timestamp < best_timestamp:
                    best_timestamp = timestamp
                    best_name = name
                elif timestamp == best_timestamp:
                    if name > best_name:
                        best_name = name

        result.append([group, best_name])

    return result

